-- CA-001E owns only coordination data; these commands cannot alter commercial or product state.
create function public.authorize_activation_operator(p_actor_id uuid,p_tenant_id uuid,p_customer_account_id uuid)
returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin'and exists(select 1 from public.customer_accounts a where a.id=p_customer_account_id and a.tenant_id=p_tenant_id))$$;
create function public.assign_activation_owner(p_actor_id uuid,p_assignment jsonb,p_expected_revision integer,p_correlation_id text)
returns public.activation_assignments language plpgsql security definer set search_path=''as $$
declare v_current public.activation_assignments;v_result public.activation_assignments;
begin if not public.authorize_activation_operator(p_actor_id,(p_assignment->>'tenantId')::uuid,(p_assignment->>'customerAccountId')::uuid)then raise exception'ACTIVATION_NOT_AUTHORIZED';end if;
 select*into v_current from public.activation_assignments where customer_account_id=(p_assignment->>'customerAccountId')::uuid and coalesce(product_family,'')=coalesce(p_assignment->>'productFamily','')and coalesce(journey_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(nullif(p_assignment->>'journeyId','')::uuid,'00000000-0000-0000-0000-000000000000'::uuid)and status='active'for update;
 if found then if v_current.revision<>p_expected_revision then raise exception'STALE_ACTIVATION_REVISION';end if;update public.activation_assignments set status='cancelled',completed_at=now(),revision=revision+1 where id=v_current.id;end if;
 insert into public.activation_assignments(id,tenant_id,customer_account_id,product_family,journey_id,assigned_operator_id,assigned_by,status,reason_code,assigned_at,revision)values((p_assignment->>'id')::uuid,(p_assignment->>'tenantId')::uuid,(p_assignment->>'customerAccountId')::uuid,p_assignment->>'productFamily',nullif(p_assignment->>'journeyId','')::uuid,(p_assignment->>'assignedOperatorId')::uuid,p_actor_id,'active',p_assignment->>'reasonCode',(p_assignment->>'assignedAt')::timestamptz,1)returning*into v_result;
 insert into public.activation_assignment_history(tenant_id,assignment_id,from_operator_id,to_operator_id,actor_id,reason_code,revision,correlation_id,occurred_at)values(v_result.tenant_id,v_result.id,v_current.assigned_operator_id,v_result.assigned_operator_id,p_actor_id,coalesce(v_result.reason_code,'OPERATIONAL_ASSIGNMENT'),v_result.revision,p_correlation_id,now());return v_result;end$$;
create function public.add_activation_internal_note(p_actor_id uuid,p_note jsonb,p_correlation_id text)returns void language plpgsql security definer set search_path=''as $$begin if not public.authorize_activation_operator(p_actor_id,(p_note->>'tenantId')::uuid,(p_note->>'customerAccountId')::uuid)then raise exception'ACTIVATION_NOT_AUTHORIZED';end if;insert into public.activation_internal_notes(id,tenant_id,customer_account_id,product_family,journey_id,body,created_by,created_at)values((p_note->>'id')::uuid,(p_note->>'tenantId')::uuid,(p_note->>'customerAccountId')::uuid,p_note->>'productFamily',nullif(p_note->>'journeyId','')::uuid,p_note->>'body',p_actor_id,(p_note->>'createdAt')::timestamptz);end$$;
create function public.add_activation_customer_guidance(p_actor_id uuid,p_guidance jsonb,p_correlation_id text)returns void language plpgsql security definer set search_path=''as $$begin if not public.authorize_activation_operator(p_actor_id,(p_guidance->>'tenantId')::uuid,(p_guidance->>'customerAccountId')::uuid)then raise exception'ACTIVATION_NOT_AUTHORIZED';end if;insert into public.activation_customer_guidance(id,tenant_id,customer_account_id,product_family,journey_id,guidance_code,customer_safe_message,created_by,created_at)values((p_guidance->>'id')::uuid,(p_guidance->>'tenantId')::uuid,(p_guidance->>'customerAccountId')::uuid,p_guidance->>'productFamily',nullif(p_guidance->>'journeyId','')::uuid,p_guidance->>'guidanceCode',p_guidance->>'customerSafeMessage',p_actor_id,(p_guidance->>'createdAt')::timestamptz);end$$;
create function public.record_activation_admin_operation(p_actor_id uuid,p_operation jsonb)returns void language plpgsql security definer set search_path=''as $$declare v_operation_id uuid;begin if not public.authorize_activation_operator(p_actor_id,(p_operation->>'tenantId')::uuid,(p_operation->>'customerAccountId')::uuid)then raise exception'ACTIVATION_NOT_AUTHORIZED';end if;insert into public.activation_admin_operations(tenant_id,customer_account_id,actor_id,action_code,correlation_id,idempotency_key_hash,status,upstream_reference_type,upstream_reference_id,created_at,completed_at)values((p_operation->>'tenantId')::uuid,(p_operation->>'customerAccountId')::uuid,p_actor_id,p_operation->>'actionCode',p_operation->>'correlationId',p_operation->>'hash','completed','authoritative_application_operation',p_operation->>'upstreamReferenceId',now(),now())on conflict(idempotency_key_hash)do nothing returning id into v_operation_id;if v_operation_id is not null then insert into public.activation_admin_audit_events(tenant_id,customer_account_id,operation_id,event_type,actor_id,outcome,correlation_id)values((p_operation->>'tenantId')::uuid,(p_operation->>'customerAccountId')::uuid,v_operation_id,'activation_'||lower(p_operation->>'actionCode'),p_actor_id,'completed',p_operation->>'correlationId');end if;end$$;
revoke all on function public.authorize_activation_operator(uuid,uuid,uuid),public.assign_activation_owner(uuid,jsonb,integer,text),public.add_activation_internal_note(uuid,jsonb,text),public.add_activation_customer_guidance(uuid,jsonb,text),public.record_activation_admin_operation(uuid,jsonb)from public,anon,authenticated;
